import typing as T

from mn_prompts.layers.models import Layer
from mn_prompts.prompts.rules.get_prompts_dir import get_prompts_dir

GENERATED_COMMENT = (
    "[comment]: <> (This file is generated by mn-prompts. Do not edit directly.)"
)


def get_index_text(layers: T.List[Layer]) -> str:
    template = (get_prompts_dir() / "index_template.md").read_text()
    snippets = "\n\n".join(layer.snippet for layer in layers)
    return GENERATED_COMMENT + "\n\n" + template.replace("{{layers}}", snippets)
